INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10201, 'ក្នុងវិធីចែកពហុធា \(A = B \times Q + R\) តើលក្ខខណ្ឌនៃសំណល់ \(R\) ត្រូវផ្ទៀងផ្ទាត់អ្វី?', NULL, '["\\(\\deg(R) = \\deg(B)\\)", "\\(\\deg(R) < \\deg(B)\\) ឬ \\(R = 0\\)", "\\(\\deg(R) > \\deg(B)\\)", "\\(\\deg(R) = \\deg(Q)\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យវិធីចែកអឺគ្លីដនៃពហុធា សំណល់ត្រូវមានដឺក្រេតូចជាងដឺក្រេនៃតួចែក ឬសំណល់ស្មើនឹងសូន្យ។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10202, 'តួចែករួមធំបំផុត (GCD) នៃឯកធា \(12x^3y^2\) និង \(18x^2y^4\) គឺ៖', NULL, '["\\(36x^3y^4\\)", "\\(2x^2y^2\\)", "\\(6x^2y^2\\)", "\\(6x^3y^4\\)"]', 2, NULL, 1, 'mcq', 'យកកត្តារួមដែលមាននិទស្សន្តតូចជាងគេ៖ \(\text{GCD}(12,18)=6\), \(x^{\min(3,2)}=x^2\), \(y^{\min(2,4)}=y^2\) នាំឱ្យបាន \(6x^2y^2\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10203, 'កន្សោមប្រភាគ \(\frac{2x+3}{x-4}\) គ្មានន័យ (មិនអាចកំណត់បាន) កាលណា \(x\) ស្មើនឹង៖', NULL, '["\\(-4\\)", "\\(0\\)", "\\(-\\frac{3}{2}\\)", "\\(4\\)"]', 3, NULL, 1, 'mcq', 'កន្សោមប្រភាគគ្មានន័យកាលណាភាគបែងស្មើនឹងសូន្យ៖ \(x-4 = 0 \implies x = 4\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10204, 'បើពហុធា \(A(x)\) មានដឺក្រេ 5 ហើយតួចែក \(B(x)\) មានដឺក្រេ 2 នោះផលចែក \(Q(x)\) មានដឺក្រេស្មើនឹង៖', NULL, '["\\(7\\)", "\\(10\\)", "\\(2\\)", "\\(3\\)"]', 3, NULL, 1, 'mcq', 'ដឺក្រេនៃផលចែកគឺ \(\deg(Q) = \deg(A) - \deg(B) = 5 - 2 = 3\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10205, 'ពហុគុណរួមតូចបំផុត (LCM) នៃ \(4x^2\) និង \(6x^3\) គឺ៖', NULL, '["\\(2x^2\\)", "\\(24x^5\\)", "\\(12x^2\\)", "\\(12x^3\\)"]', 3, NULL, 1, 'mcq', 'យកកត្តារួមនិងមិនរួមដែលមាននិទស្សន្តធំជាងគេ៖ \(\text{LCM}(4,6)=12\), \(x^{\max(2,3)}=x^3\) នាំឱ្យបាន \(12x^3\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10206, 'សម្រួលកន្សោមប្រភាគ \(\frac{x^2 - 9}{x - 3}\) ចំពោះ \(x \ne 3\) ទទួលបាន៖', NULL, '["\\(x - 3\\)", "\\(x + 3\\)", "\\(x + 9\\)", "\\(x^2 - 3\\)"]', 1, NULL, 1, 'mcq', '\(\frac{x^2-9}{x-3} = \frac{(x-3)(x+3)}{x-3} = x+3\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10207, 'បើគេថាពហុធា \(A(x)\) ចែកដាច់នឹងពហុធា \(B(x)\) នោះមានន័យថាសំណល់ \(R(x)\) ស្មើនឹង៖', NULL, '["\\(1\\)", "\\(0\\)", "\\(B(x)\\)", "\\(x\\)"]', 1, NULL, 1, 'mcq', 'វិធីចែកដាច់គឺជាវិធីចែកដែលមានសំណល់ស្មើនឹង 0។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10208, 'គណនាផលបូកប្រភាគដែលមានភាគបែងដូចគ្នា \(\frac{2x}{x+1} + \frac{2}{x+1}\) ចំពោះ \(x \ne -1\)៖', NULL, '["\\(\\frac{4x}{x+1}\\)", "\\(2x+2\\)", "\\(\\frac{2x+2}{(x+1)^2}\\)", "\\(2\\)"]', 3, NULL, 1, 'mcq', '\(\frac{2x+2}{x+1} = \frac{2(x+1)}{x+1} = 2\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10209, 'គណនាផលដក \(\frac{3x+5}{x-2} - \frac{2x+7}{x-2}\) ចំពោះ \(x \ne 2\)៖', NULL, '["\\(\\frac{x+12}{x-2}\\)", "\\(\\frac{5x+12}{x-2}\\)", "\\(1\\)", "\\(-1\\)"]', 2, NULL, 1, 'mcq', '\(\frac{(3x+5)-(2x+7)}{x-2} = \frac{x-2}{x-2} = 1\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10210, 'គណនាផលគុណកន្សោមប្រភាគ \(\frac{x}{y} \times \frac{y^2}{x^2}\) ចំពោះ \(x, y \ne 0\)៖', NULL, '["\\(\\frac{x}{y}\\)", "\\(\\frac{y^2}{x}\\)", "\\(\\frac{y}{x}\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', '\(\frac{x \times y^2}{y \times x^2} = \frac{y}{x}\)។', 'ប្រមាណវិធីចែកពហុធា', 'easy', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10211, 'ផលចែកនៃវិធីចែក \((x^2 + 6x - 55) \div (x - 5)\) គឺ៖', NULL, '["\\(x - 11\\)", "\\(x + 11\\)", "\\(x - 5\\)", "\\(x + 5\\)"]', 1, NULL, 2, 'mcq', 'ដោយ \(x^2+6x-55 = (x-5)(x+11)\) នោះផលចែកគឺ \(x+11\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10212, 'តួចែករួមធំបំផុត (GCD) នៃកន្សោម \(x^2(x-1)\) និង \(x(x-1)(x+1)\) គឺ៖', NULL, '["\\(x^2(x^2-1)\\)", "\\(x^2(x-1)\\)", "\\(x(x-1)\\)", "\\(x - 1\\)"]', 2, NULL, 2, 'mcq', 'កត្តារួមដែលមាននិទស្សន្តតូចជាងគេគឺ \(x\) និង \(x-1\) នាំឱ្យ GCD គឺ \(x(x-1)\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10213, 'សម្រួលកន្សោមប្រភាគ \(\frac{x^2 - 1}{x^3 + 1}\) ទទួលបាន៖', NULL, '["\\(\\frac{x-1}{x^2 - x + 1}\\)", "\\(\\frac{x-1}{x^2 + 1}\\)", "\\(\\frac{x+1}{x^2 + x + 1}\\)", "\\(\\frac{1}{x+1}\\)"]', 0, NULL, 2, 'mcq', '\(\frac{(x-1)(x+1)}{(x+1)(x^2-x+1)} = \frac{x-1}{x^2-x+1}\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10214, 'ផលចែកនៃវិធីចែក \((6x^2 + 5x - 4) \div (2x - 1)\) គឺ៖', NULL, '["\\(3x + 1\\)", "\\(3x + 4\\)", "\\(3x - 4\\)", "\\(2x + 4\\)"]', 1, NULL, 2, 'mcq', '\(6x^2+5x-4 = (2x-1)(3x+4)\) ដូច្នេះផលចែកគឺ \(3x+4\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10215, 'ពហុគុណរួមតូចបំផុត (LCM) នៃកន្សោម \(x^2(x-1)\) និង \(x(x-1)(x+1)\) គឺ៖', NULL, '["\\(x^3(x-1)^2\\)", "\\(x(x-1)\\)", "\\(x^2(x^2-1)\\)", "\\(x(x^2-1)\\)"]', 2, NULL, 2, 'mcq', '\(\text{LCM} = x^2(x-1)(x+1) = x^2(x^2-1)\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10216, 'សម្រួលកន្សោមប្រភាគ \(\frac{2x^2 - x - 1}{x^3 - 1}\) ទទួលបាន៖', NULL, '["\\(\\frac{1}{x-1}\\)", "\\(\\frac{2x+1}{x^2 + x + 1}\\)", "\\(\\frac{2x+1}{x^2 - x + 1}\\)", "\\(\\frac{2x-1}{x^2 + x + 1}\\)"]', 1, NULL, 2, 'mcq', '\(\frac{(x-1)(2x+1)}{(x-1)(x^2+x+1)} = \frac{2x+1}{x^2+x+1}\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10217, 'រកសំណល់នៃវិធីចែក \((4x - 5) \div (x + 2)\)៖', NULL, '["\\(-5\\)", "\\(-13\\)", "\\(13\\)", "\\(3\\)"]', 1, NULL, 2, 'mcq', '\(4x-5 = 4(x+2) - 13\) ដូច្នេះសំណល់គឺ \(-13\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10218, 'តួចែករួមធំបំផុត (GCD) នៃពហុធា \(4x^2 - 16\) និង \(4x^2 - 2x - 12\) គឺ៖', NULL, '["\\(2(x - 2)\\)", "\\(x - 2\\)", "\\(4(x - 2)\\)", "\\(2(x + 2)\\)"]', 0, NULL, 2, 'mcq', '\(4x^2-16 = 4(x-2)(x+2)\) និង \(4x^2-2x-12 = 2(2x+3)(x-2)\)។ កត្តារួមគឺ \(2(x-2)\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10219, 'គណនាផលបូក \(\frac{1}{1+a} + \frac{2a}{1-a^2}\) ចំពោះ \(a \ne \pm 1\)៖', NULL, '["\\(\\frac{2a+1}{1-a^2}\\)", "\\(\\frac{1+3a}{1-a^2}\\)", "\\(\\frac{1}{1+a}\\)", "\\(\\frac{1}{1-a}\\)"]', 3, NULL, 2, 'mcq', '\(\frac{1-a+2a}{1-a^2} = \frac{1+a}{(1-a)(1+a)} = \frac{1}{1-a}\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10220, 'ផលចែកនៃវិធីចែក \((x^3 - x^2 + x - 1) \div (x + 2)\) គឺ៖', NULL, '["\\(x^2 - 3x - 7\\)", "\\(x^2 + x + 3\\)", "\\(x^2 - x + 1\\)", "\\(x^2 - 3x + 7\\)"]', 3, NULL, 2, 'mcq', 'តាមវិធីចែកជួរឈរ \(x^3 - x^2 + x - 1 = (x+2)(x^2-3x+7) - 15\) ផលចែកគឺ \(x^2-3x+7\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10221, 'គណនា \(\frac{x^2-4}{x^2+4x+4} \div \frac{x-2}{x+2}\) ចំពោះ \(x \ne \pm 2\)៖', NULL, '["\\(\\frac{(x-2)^2}{(x+2)^2}\\)", "\\(x-2\\)", "\\(1\\)", "\\(\\frac{1}{x+2}\\)"]', 2, NULL, 2, 'mcq', '\(\frac{(x-2)(x+2)}{(x+2)^2} \times \frac{x+2}{x-2} = \frac{x-2}{x+2} \times \frac{x+2}{x-2} = 1\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10222, 'ពេលចែក \(3x^2 + 2x + 1\) នឹង \(3x - 4\) គេទទួលបានផលចែកនិងសំណល់រៀងគ្នាគឺ៖', NULL, '["ផលចែក \\(x - 2\\) និងសំណល់ \\(-7\\)", "ផលចែក \\(3x + 2\\) និងសំណល់ \\(1\\)", "ផលចែក \\(x + 2\\) និងសំណល់ \\(-9\\)", "ផលចែក \\(x + 2\\) និងសំណល់ \\(9\\)"]', 3, NULL, 2, 'mcq', '\(3x^2+2x+1 = (3x-4)(x+2) + 9\) ផលចែកគឺ \(x+2\) និងសំណល់គឺ \(9\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10223, 'គណនា \(\frac{x^2-49}{x^2+2x} \times \frac{x+2}{x-7}\) ចំពោះ \(x \ne 0, -2, 7\)៖', NULL, '["\\(\\frac{x(x+7)}{x+2}\\)", "\\(\\frac{x+7}{x}\\)", "\\(\\frac{x+7}{x+2}\\)", "\\(\\frac{x-7}{x}\\)"]', 1, NULL, 2, 'mcq', '\(\frac{(x-7)(x+7)}{x(x+2)} \times \frac{x+2}{x-7} = \frac{x+7}{x}\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10224, 'សម្រួលកន្សោមប្រភាគជាន់ \(\frac{x - \frac{1}{x}}{1 - \frac{1}{x}}\) ចំពោះ \(x \ne 0, 1\)៖', NULL, '["\\(x + 1\\)", "\\(x - 1\\)", "\\(1\\)", "\\(\\frac{x+1}{x}\\)"]', 0, NULL, 2, 'mcq', '\(\frac{\frac{x^2-1}{x}}{\frac{x-1}{x}} = \frac{x^2-1}{x-1} = x+1\)។', 'ប្រមាណវិធីចែកពហុធា', 'medium', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10225, 'កន្សោមពីជគណិត \(P(x)\) មួយចែកនឹង \(3x^2+1\) បានផលចែក \(x^3-2\) និងសំណល់ \(4x-5\)។ រក \(P(x)\)៖', NULL, '["\\(3x^5 + x^3 - 6x^2 + 4x - 7\\)", "\\(3x^5 - x^3 - 6x^2 + 4x - 3\\)", "\\(3x^5 + 6x^2 - 4x - 7\\)", "\\(3x^5 + x^3 - 6x^2 - 4x + 7\\)"]', 0, NULL, 3, 'mcq', '\(P(x) = (3x^2+1)(x^3-2) + (4x-5) = 3x^5 - 6x^2 + x^3 - 2 + 4x - 5 = 3x^5 + x^3 - 6x^2 + 4x - 7\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10226, 'គណនាតម្លៃនៃកន្សោម \(\frac{1}{x-1} - \frac{1}{x+1} - \frac{2}{x^2+1} - \frac{4}{x^4+1}\)៖', NULL, '["\\(\\frac{4}{x^8-1}\\)", "\\(\\frac{16}{x^8-1}\\)", "\\(\\frac{8}{x^8+1}\\)", "\\(\\frac{8}{x^8-1}\\)"]', 3, NULL, 3, 'mcq', 'បង្រួមជាបន្តបន្ទាប់៖ \(\frac{2}{x^2-1} - \frac{2}{x^2+1} = \frac{4}{x^4-1}\) រួច \(\frac{4}{x^4-1} - \frac{4}{x^4+1} = \frac{8}{x^8-1}\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10227, 'សម្រួលកន្សោមប្រភាគ \(\frac{\frac{a+2}{2}}{a - \frac{2}{a+1}}\) ទទួលបាន៖', NULL, '["\\(\\frac{a+1}{2a-2}\\)", "\\(\\frac{a-1}{2a+2}\\)", "\\(\\frac{a+1}{a-1}\\)", "\\(\\frac{a+2}{2a-1}\\)"]', 0, NULL, 3, 'mcq', '\(a - \frac{2}{a+1} = \frac{(a+2)(a-1)}{a+1}\) នាំឱ្យ \(\frac{a+2}{2} \times \frac{a+1}{(a+2)(a-1)} = \frac{a+1}{2(a-1)}\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10228, 'គេមានពហុធាពីរដែលមាន \(\text{GCD} = x-2\) និង \(\text{LCM} = 3x^3+8x^2-13x-30 = (x-2)(x+3)(3x+5)\)។ បើពហុធាមួយគឺ \(3x^2-x-10\) នោះពហុធាមួយទៀតគឺ៖', NULL, '["\\(x^2 + 5x + 6\\)", "\\(3x^2 + x - 6\\)", "\\(x^2 - x - 6\\)", "\\(x^2 + x - 6\\)"]', 3, NULL, 3, 'mcq', '\(3x^2-x-10 = (x-2)(3x+5)\) ដូច្នេះពហុធាមួយទៀតគឺ \((x-2)(x+3) = x^2+x-6\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10229, 'ពេលចែក \(6x^4-7x^3-4x^2+5x+3\) នឹងកន្សោមពីជគណិត \(B(x)\) គេបានផលចែក \(2x^2-3x+1\) និងសំណល់ \(-2x+5\)។ រកកន្សោម \(B(x)\)៖', NULL, '["\\(2x^2 + x - 3\\)", "\\(3x^2 + 2x - 1\\)", "\\(3x^2 + x - 2\\)", "\\(3x^2 - x + 2\\)"]', 2, NULL, 3, 'mcq', '\(B(x) = \frac{A - R}{Q} = \frac{6x^4-7x^3-4x^2+7x-2}{2x^2-3x+1} = 3x^2 + x - 2\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10230, 'គណនាផលបូកកន្សោម \(\frac{a^2-bc}{(a+b)(c+a)} + \frac{b^2-ca}{(b+c)(a+b)} + \frac{c^2-ab}{(c+a)(b+c)}\)៖', NULL, '["\\(a+b+c\\)", "\\(\\frac{1}{abc}\\)", "\\(1\\)", "\\(0\\)"]', 3, NULL, 3, 'mcq', 'តម្រូវភាគបែងរួម \((a+b)(b+c)(c+a)\) នោះភាគយកបូកសរុបស្មើនឹង 0។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10231, 'រកតម្លៃនៃចំនួនថេរ \(a\) ដើម្បីឱ្យកន្សោម \(x^3+ax^2+x+2-a\) ចែកដាច់នឹង \(x^2+2x-1\)៖', NULL, '["\\(-3\\)", "\\(3\\)", "\\(1\\)", "\\(2\\)"]', 1, NULL, 3, 'mcq', 'ធ្វើវិធីចែកជួរឈរ សំណល់គឺ \((6-2a)x\)។ ដើម្បីចែកដាច់ \(6-2a = 0 \implies a = 3\)។', 'ប្រមាណវិធីចែកពហុធា', 'hard', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10232, 'ប្រអប់សំបុត្ររាងប្រលេពីប៉ែតកែងមួយមានមាឌ \(V = W^3 + 10W^2 + 16W\)។ បាតនៃប្រអប់មានបណ្តោយ \(AB = W + 8\) និងទទឹង \(BC = W\)។ រកកម្ពស់ \(BB''\) នៃប្រអប់៖', NULL, '["\\(W - 2\\)", "\\(W + 2\\)", "\\(W + 4\\)", "\\(W + 8\\)"]', 1, NULL, 3, 'mcq', 'មាឌគឺ \(V = AB \times BC \times BB'' = W(W+8) \times BB''\)។ ដោយ \(V = W(W+2)(W+8)\) នាំឱ្យ \(BB'' = W+2\)។', 'ប្រមាណវិធីចែកពហុធា', 'pisa', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10233, 'ផ្ទាំងរូបភាពរាងចតុកោណកែងមួយមានបណ្តោយ \(x+5\) និងទទឹង \(x+3\)។ នៅខាងក្នុងមានរូបថតមួយរាងចតុកោណកែងមានបណ្តោយ \(2x+1\) និងទទឹង \(x\)។ រកកន្សោមតាងផ្ទៃនៃផ្នែកពណ៌ក្រម៉ៅ (ផ្ទៃស៊ុមក្រៅរូបថត)៖', NULL, '["\\(-x^2 + 7x + 15\\)", "\\(3x^2 + 9x + 15\\)", "\\(x^2 + 7x + 15\\)", "\\(-x^2 + 9x + 15\\)"]', 0, NULL, 3, 'mcq', 'ផ្ទៃផ្ទាំងធំគឺ \((x+5)(x+3) = x^2+8x+15\)។ ផ្ទៃរូបថតក្នុងគឺ \(x(2x+1) = 2x^2+x\)។ ផ្ទៃក្រម៉ៅគឺ \((x^2+8x+15)-(2x^2+x) = -x^2+7x+15\)។', 'ប្រមាណវិធីចែកពហុធា', 'pisa', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10234, 'ទុយោទឹក A បង្ហូរពេញអាងក្នុងរយៈពេល \(x\) ម៉ោង រីឯទុយោ B ចំណាយ \(x+3\) ម៉ោង។ តើកន្សោមប្រភាគណាដែលតាងរយៈពេល (ជាម៉ោង) ពេលបើកទុយោទាំងពីរបញ្ចូលគ្នា?', NULL, '["\\(\\frac{x+3}{2}\\)", "\\(\\frac{x^2+3}{2x}\\)", "\\(\\frac{2x+3}{x^2+3x}\\)", "\\(\\frac{x^2+3x}{2x+3}\\)"]', 3, NULL, 3, 'mcq', 'ល្បឿនរួមគឺ \(\frac{1}{x} + \frac{1}{x+3} = \frac{2x+3}{x(x+3)}\)។ ដូច្នេះរយៈពេលបំពេញគឺ \(T = \frac{x(x+3)}{2x+3} = \frac{x^2+3x}{2x+3}\)។', 'ប្រមាណវិធីចែកពហុធា', 'pisa', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10235, 'រោងពុម្ពមួយចំណាយថ្លៃដើមថេរ \(1\,200\) ដុល្លារ និងថ្លៃបោះពុម្ព \(4\) ដុល្លារក្នុងមួយក្បាល។ ថ្លៃដើមមធ្យមក្នុងមួយក្បាលគឺ \(C_{\text{avg}}(x) = \frac{1\,200 + 4x}{x}\)។ តើត្រូវបោះពុម្ពសៀវភៅប៉ុន្មានក្បាលទើបថ្លៃដើមមធ្យមចុះមកនៅត្រឹម \(6\) ដុល្លារក្នុងមួយក្បាល?', NULL, '["800 ក្បាល", "400 ក្បាល", "600 ក្បាល", "500 ក្បាល"]', 2, NULL, 3, 'mcq', '\(\frac{1\,200+4x}{x} = 6 \iff 1\,200+4x = 6x \iff 2x = 1\,200 \iff x = 600\) ក្បាល។', 'ប្រមាណវិធីចែកពហុធា', 'pisa', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10236, 'ចតុកោណកែងមួយមានបណ្តោយលើសទទឹង \(3\text{ m}\)។ បើបណ្តោយកើនឡើង \(2\text{ m}\) ហើយទទឹងថយចុះ \(1\text{ m}\) នោះផ្ទៃក្រឡានៅដដែល។ រកទទឹងនិងបណ្តោយដើមនៃចតុកោណកែង៖', NULL, '["ទទឹង \\(6\\text{ m}\\) និងបណ្តោយ \\(9\\text{ m}\\)", "ទទឹង \\(4\\text{ m}\\) និងបណ្តោយ \\(7\\text{ m}\\)", "ទទឹង \\(5\\text{ m}\\) និងបណ្តោយ \\(10\\text{ m}\\)", "ទទឹង \\(5\\text{ m}\\) និងបណ្តោយ \\(8\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'តាងទទឹងដោយ \(x\) បណ្តោយ \(x+3\)។ សមីការ \(x(x+3) = (x-1)(x+5) \iff x^2+3x = x^2+4x-5 \iff x = 5\)។ ទទឹង 5m និងបណ្តោយ 8m។', 'ប្រមាណវិធីចែកពហុធា', 'pisa', 1, '10', 'ប្រមាណវិធីចែកពហុធា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10237, 'គេឱ្យកន្សោមប្រភាគ \(F(x) = \frac{5x - 1}{2x - 6}\)។
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10238, 'ធ្វើប្រមាណវិធីចែកពហុធា \((x^2 + 6x - 55) \div (x - 5)\) និងបង្ហាញពីជំហានគណនា។', NULL, '[]', 0, NULL, 5, 'writing', 'ដាក់កន្សោមតំណាងចែកជាផលគុណកត្តា: \(x^2+6x-55 = (x-5)(x+11)\) (3 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10239, 'រកតួចែករួមធំបំផុត (GCD) និងពហុគុណរួមតូចបំផុត (LCM) នៃឯកធា \(A = 54x^3y^5\) និង \(B = 36x^4y^2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បំបែកជាផលគុណកត្តាបឋម: \(A = 2 \times 3^3 \times x^3 \times y^5\) និង \(B = 2^2 \times 3^2 \times x^4 \times y^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10240, 'សម្រួលកន្សោមប្រភាគសនិទាន \(\frac{2x^2 - x - 1}{x^3 - 1}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ដាក់ភាគយកជាផលគុណកត្តា: \(2x^2-x-1 = (x-1)(2x+1)\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10241, 'គណនាកន្សោមប្រភាគ \(\frac{x+8}{x^2+x-2} - \frac{x+4}{x^2+3x+2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បំបែកភាគបែងជាកត្តា: \(x^2+x-2 = (x+2)(x-1)\) និង \(x^2+3x+2 = (x+2)(x+1)\) រួចរកភាគបែងរួម \((x+2)(x-1)(x+1)\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10242, 'ធ្វើវិធីចែកតាមជួរឈរ \((2x^3 - 3x^2 - x + 4) \div (2x^2 + 2x - 3)\) រួចសរសេរទម្រង់ \(A = B \times Q + R\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រៀបចំជួរឈរ និងចែកតួដំបូង \(2x^3 \div 2x^2 = x\) រួចគុណដកទទួលបាន \(-5x^2 + 2x + 4\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10243, 'ស្រាយបញ្ជាក់សមភាព: \(\frac{1}{x-1} - \frac{1}{x+1} - \frac{2}{x^2+1} - \frac{4}{x^4+1} = \frac{8}{x^8-1}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលដកពីរតួដំបូង: \(\frac{1}{x-1} - \frac{1}{x+1} = \frac{(x+1)-(x-1)}{x^2-1} = \frac{2}{x^2-1}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10244, 'ពេលចែក \(6x^4-7x^3-4x^2+5x+3\) នឹងកន្សោម \(P(x)\) គេបានផលចែក \(2x^2-3x+1\) និងសំណល់ \(-2x+5\)។ ចូរកំណត់កន្សោម \(P(x)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើទំនាក់ទំនងវិធីចែក: \(A = P \times Q + R \implies P \times Q = A - R\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10245, 'រកតម្លៃនៃចំនួនថេរ \(a\) ដែលធ្វើឱ្យកន្សោម \(x^3+ax^2+x+2-a\) ចែកដាច់នឹង \(x^2+2x-1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ធ្វើវិធីចែកជួរឈរ: តួទីមួយបាន \(x\) សំណល់បន្ទាប់គឺ \((a-2)x^2 + 2x + 2 - a\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10246, 'ប្រអប់សំបុត្រមួយរាងប្រលេពីប៉ែតកែងមានមាឌ \(V = W^3 + 10W^2 + 16W\)។ បាតនៃប្រអប់មានបណ្តោយ \(AB = W + 8\) និងទទឹង \(BC = W\)។ គណនាប្រវែងកម្ពស់ \(BB''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តមាឌប្រលេពីប៉ែត: \(V = AB \times BC \times BB'' \implies BB'' = \frac{V}{AB \times BC}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10247, 'ផ្ទាំងរូបភាពរាងចតុកោណកែងមួយមានបណ្តោយ \(x+5\) និងទទឹង \(x+3\)។ ខាងក្នុងមានរូបថតរាងចតុកោណកែងមានបណ្តោយ \(2x+1\) និងទទឹង \(x\)។
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10248, 'ការេចំនួនគត់ដែលធំ នៃចំនួនគត់ពីរជាប់គ្នា លើសផលគុណនៃចំនួនគត់ជាប់គ្នានោះចំនួន \(10\)។ ចូរស្វែងរកចំនួនគត់ទាំងពីរនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងចំនួនគត់តូចដោយ \(n\) នោះចំនួនគត់ធំជាប់គ្នាគឺ \(n+1\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10249, 'ម៉ាស៊ីនបូមទឹកពីរ A និង B បូមទឹកចូលអាងស្តុកមួយ។ ម៉ាស៊ីន A ចំណាយពេល \(x\) ម៉ោង រីឯម៉ាស៊ីន B ចំណាយ \(x+5\) ម៉ោង។ បើដំណើរការម៉ាស៊ីនទាំងពីរព្រមគ្នា គេចំណាយពេល \(6\) ម៉ោងទើបពេញអាង។
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10250, 'ដីឡូត៍រាងចតុកោណកែងមួយមានបណ្តោយស្មើពីរដងទទឹង។ ប្រសិនបើបណ្តោយថយចុះ \(4\text{ m}\) ហើយទទឹងកើនឡើង \(3\text{ m}\) នោះផ្ទៃក្រឡារបស់ដីឡូត៍នៅដដែល។ រកវិមាត្រដើមនៃដីឡូត៍នេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងទទឹងដើមដោយ \(x\) (\(x > 0\)) នាំឱ្យបណ្តោយដើមគឺ \(2x\) និងផ្ទៃដើមគឺ \(S_1 = 2x^2\) (1 ពិន្ទុ)
